messages.content:
Tool response:
Tool: check_availability_and_delivery_options
Description: Check real-time store availability and delivery options for a specific product at a given store.
Parameters:
    {
      "type": "object",
      "properties": {
        "store_address": {
          "type": "string",
          "description": "Full address of the store",
          "title": "Store Address"
        },
        "product_model": {
          "type": "string",
          "description": "Model number of the product",
          "title": "Product Model"
        }
      },
      "required": [
        "store_address",
        "product_model"
      ]
    }
